<?php use Addons\Grh\GrhService as S; require __DIR__ . '/_h.php'; $paie = can('grh.paie'); ?>
<div class="d-flex flex-wrap gap-2 align-items-end mb-2"><form method="get" class="d-flex flex-wrap gap-2 align-items-end">
  <div><label class="form-label small mb-0"><?= e(t('Recherche')) ?></label><input name="q" value="<?= e($q) ?>" class="form-control form-control-sm" placeholder="<?= e(t('Nom, matricule, téléphone')) ?>"></div>
  <div><label class="form-label small mb-0"><?= e(t('Département')) ?></label><select name="departement" class="form-select form-select-sm"><option value=""><?= e(t('Tous')) ?></option><?php foreach ($deps as $x): ?><option value="<?= (int) $x['id'] ?>" <?= $dep === (int) $x['id'] ? 'selected' : '' ?>><?= e($x['name']) ?></option><?php endforeach; ?></select></div>
  <div><label class="form-label small mb-0"><?= e(t('État')) ?></label><select name="status" class="form-select form-select-sm"><option value="tous" <?= !isset(S::EMP_STATUS[$status]) ? 'selected' : '' ?>><?= e(t('Tous')) ?></option><?php foreach (S::EMP_STATUS as $k => $l): ?><option value="<?= e($k) ?>" <?= $status === $k ? 'selected' : '' ?>><?= e(t($l)) ?></option><?php endforeach; ?></select></div>
  <button class="btn btn-sm btn-primary"><i class="bi bi-search"></i></button></form>
  <span class="small text-secondary"><?= (int) $p['total'] ?> <?= e(t('employé(s)')) ?></span>
  <?php if (can('reports.export')): ?><a class="btn btn-sm btn-outline-success ms-auto" href="<?= e(query_with(['export' => 'csv'])) ?>"><i class="bi bi-filetype-csv"></i> CSV</a><a class="btn btn-sm btn-outline-danger" href="<?= e(query_with(['export' => 'pdf'])) ?>"><i class="bi bi-filetype-pdf"></i> PDF</a><?php endif; ?>
  <?php if (can('grh.manage')): ?><a class="btn btn-sm btn-primary <?= can('reports.export') ? '' : 'ms-auto' ?>" href="<?= e(url('/grh/employes/fiche')) ?>"><i class="bi bi-person-plus"></i> <?= e(t('Nouvel employé')) ?></a><?php endif; ?></div>
<div class="card"><div class="table-responsive"><table class="table table-sm align-middle mb-0"><thead><tr><th><?= e(t('Matricule')) ?></th><th><?= e(t('Employé')) ?></th><th><?= e(t('Département et poste')) ?></th><th><?= e(t('Téléphone')) ?></th><th><?= e(t('Embauche')) ?></th><th><?= e(t('Contrat')) ?></th><?php if ($paie): ?><th class="num"><?= e(t('Salaire mensuel')) ?></th><?php endif; ?><th><?= e(t('État')) ?></th></tr></thead><tbody>
<?php foreach ($p['rows'] as $e): ?><tr><td class="small"><?= e($e['matricule']) ?></td><td><a class="fw-semibold" href="<?= e(url('/grh/employes/' . $e['id'])) ?>"><?= e($e['last_name']) ?> <?= e($e['first_name']) ?></a></td><td class="small"><?= e($e['departement']) ?><div class="text-secondary"><?= e($e['poste']) ?></div></td><td class="small"><?= e($e['phone']) ?></td>
  <td class="small text-nowrap"><?= e(fdate($e['hire_date'], false)) ?></td><td class="small"><?= $e['contrat'] ? e(t(S::CONTRACT_KINDS[$e['contrat']])) : '<span class="text-danger">' . e(t('Aucun')) . '</span>' ?><?= $e['contrat_fin'] ? '<div class="text-secondary">→ ' . e(fdate($e['contrat_fin'], false)) . '</div>' : '' ?></td>
  <?php if ($paie): ?><td class="num"><?= $e['contrat'] ? money((float) $e['base_salary'] + (float) $e['allowances']) : '' ?></td><?php endif; ?><td><?= grh_badge(S::EMP_STATUS[$e['status']], S::EMP_COLORS[$e['status']]) ?></td></tr><?php endforeach; ?>
<?php if (!$p['rows']): ?><tr><td colspan="8" class="text-center text-secondary py-4"><?= e(t('Aucun employé ne correspond.')) ?></td></tr><?php endif; ?></tbody></table></div></div>
<?php if ($p['pages'] > 1): ?><nav class="mt-2"><ul class="pagination pagination-sm"><?php for ($i = 1; $i <= $p['pages']; $i++): ?><li class="page-item <?= $i === $p['page'] ? 'active' : '' ?>"><a class="page-link" href="<?= e(query_with(['page' => $i])) ?>"><?= $i ?></a></li><?php endfor; ?></ul></nav><?php endif; ?>
